INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Datenkonsistenz dasselbe wie Datenintegrität?', 2, '[{"text": "Nein", "correct": true, "because": "Konsistenz ist Teil der Integrität"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Schwerpunkte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Datenkonsistenz?', 3, '[{"text": "Daten widerspruchsfrei halten", "correct": true, "because": "Verlässlichkeit sichern"}, {"text": "Hardware optimieren", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Netzwerk sichern", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden fördern Datenkonsistenz?', 5, '[{"text": "Transaktionen", "correct": true, "because": "Änderungen atomar"}, {"text": "Constraints", "correct": true, "because": "Regeln erzwingen"}, {"text": "Grafiktreiber", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenkonsistenz verhindert Widersprüche. b) Sie ist immer automatisch gegeben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Muss aktiv gesichert werden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Sicherung von Datenkonsistenz?', 4, '[{"text": "Datenbankregeln", "correct": false, "because": "Erzwingen Konsistenz"}, {"text": "Transaktionsmanagement", "correct": false, "because": "Sichert Änderungen"}, {"text": "Bildschirmgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenkonsistenz nur für relationale Datenbanken gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch bei NoSQL relevant"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft bei der Datenkonsistenz?', 3, '[{"text": "Foreign Keys", "correct": true, "because": "Verknüpfungen konsistent"}, {"text": "Texteditor", "correct": false, "because": "Kein Datenbanktool"}, {"text": "Grafiksoftware", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Datenkonsistenz?', 5, '[{"text": "Verlässliche Daten", "correct": true, "because": "Keine Widersprüche"}, {"text": "Einfachere Analyse", "correct": true, "because": "Konsistente Grundlage"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Hardware-Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Datenkonsistenz ist bei Transaktionen wichtig. b) Sie ist nur für große Datenbanken nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Für alle Größen relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Datenkonsistenz?', 4, '[{"text": "Datenbankregeln", "correct": false, "because": "Sichern Konsistenz"}, {"text": "Synchronisation", "correct": false, "because": "Bei Verteilung nötig"}, {"text": "Kaffeemaschine", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Datenkonsistenz immer sofort gegeben?', 2, '[{"text": "Nein", "correct": true, "because": "Kann eventual sein"}, {"text": "Ja", "correct": false, "because": "Abhängig von System"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken sichern Datenkonsistenz?', 4, '[{"text": "Primärschlüssel", "correct": true, "because": "Eindeutigkeit"}, {"text": "Transaktionen", "correct": true, "because": "Atomare Änderungen"}, {"text": "Bildschirmauflösung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Datenkonsistenz keine Rolle spielt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kritisch für Verlässlichkeit"}, {"text": "Ja", "correct": false, "because": "Wichtig für Datenqualität"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Datenkonsistenz?', 3, '[{"text": "Transaktionssicherheit", "correct": true, "because": "Verhindert Inkonsistenzen"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Richtigkeit wichtiger"}, {"text": "Minimale Kosten", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenkonsistenz schützt vor Fehlern. b) Sie ist nur für relationale Datenbanken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch NoSQL betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei Datenkonsistenz?', 5, '[{"text": "Verteilte Systeme", "correct": true, "because": "Synchronisation schwer"}, {"text": "Hohe Datenmenge", "correct": true, "because": "Komplexität steigt"}, {"text": "Monitorgröße", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Sicherung unwichtig?', 3, '[{"text": "Datenbankregeln", "correct": false, "because": "Erzwingen Konsistenz"}, {"text": "Logging", "correct": false, "because": "Nachvollziehbarkeit"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Datenkonsistenz verloren gehen?', 3, '[{"text": "Ja", "correct": true, "because": "Bei Fehlern möglich"}, {"text": "Nein", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenkonsistenz nur für Datenbanken gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Dateisysteme betroffen"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ACID bei Datenkonsistenz?', 4, '[{"text": "Sichert Transaktionen", "correct": true, "because": "Gewährleistet Konsistenz"}, {"text": "Erhöht Bandbreite", "correct": false, "because": "Kein Netzwerkeffekt"}, {"text": "Grafiken rendert", "correct": false, "because": "Irrelevant"}]');
